@Override
protected void addAdditionalSaveData(ValueOutput nbt) {
    super.addAdditionalSaveData(nbt);
    nbt.putInt("BlockStateId", Block.getId(getBlockState()));
    nbt.putBoolean("Volley", isVolley());
    nbt.putInt("Age", this.tickCount);
}

@Override
protected void readAdditionalSaveData(ValueInput nbt) {
    super.readAdditionalSaveData(nbt);
    int stateId = nbt.getIntOr("BlockStateId", -1);
    if (stateId >= 0) {
        setBlockState(Block.stateById(stateId));
    }
    setVolley(nbt.getBooleanOr("Volley", false));
    this.tickCount = nbt.getIntOr("Age", 0);
}
